/// <reference types="node" />
import { existsSync } from 'node:fs'
import { join } from 'node:path'
import type { ConfigContext, ExpoConfig } from 'expo/config'

/**
 * AeroFMS Android configuration (Continuous Native Generation – `android/` is generated by prebuild).
 *
 * Optional native integrations are build-time switches so the app always builds:
 *  - Firebase native SDK (Crashlytics, Analytics): enabled when ./google-services.json exists.
 *  - Google Mobile Ads (AdMob): enabled with AEROFMS_ENABLE_ADS=true (+ AEROFMS_ADMOB_APP_ID).
 *    Ads are additionally gated at runtime by Remote Config `ads_enabled` (default false).
 */
const GOOGLE_SERVICES = './google-services.json'
const nativeFirebase = existsSync(join(__dirname, GOOGLE_SERVICES))
const adsNative = process.env.AEROFMS_ENABLE_ADS === 'true'
/** Google's public sample AdMob app id – replace via AEROFMS_ADMOB_APP_ID for production. */
const ADMOB_APP_ID = process.env.AEROFMS_ADMOB_APP_ID ?? 'ca-app-pub-3940256099942544~3347511713'

const VERSION = '1.0.0'
const VERSION_CODE = Number(process.env.AEROFMS_VERSION_CODE ?? 1)

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: 'AeroFMS - FMC & MCDU Simulator',
  slug: 'aerofms',
  scheme: 'aerofms',
  version: VERSION,
  orientation: 'default',
  icon: './assets/icon.png',
  userInterfaceStyle: 'dark',
  backgroundColor: '#0B1018',
  primaryColor: '#4FB3A9',
  description: 'Multi-aircraft FMC & MCDU simulator for flight simulation and training. Not for real-world navigation.',
  platforms: ['android'],
  android: {
    package: 'dev.heonhwi.areofms',
    versionCode: VERSION_CODE,
    adaptiveIcon: {
      backgroundColor: '#0B1018',
      foregroundImage: './assets/android-icon-foreground.png',
      backgroundImage: './assets/android-icon-background.png',
      monochromeImage: './assets/android-icon-monochrome.png',
    },
    predictiveBackGestureEnabled: true,
    permissions: ['android.permission.INTERNET', 'android.permission.ACCESS_NETWORK_STATE', 'android.permission.ACCESS_WIFI_STATE', 'android.permission.VIBRATE'],
    blockedPermissions: [
      'android.permission.RECORD_AUDIO',
      'android.permission.ACCESS_FINE_LOCATION',
      'android.permission.ACCESS_COARSE_LOCATION',
      'android.permission.READ_EXTERNAL_STORAGE',
      'android.permission.WRITE_EXTERNAL_STORAGE',
      'android.permission.SYSTEM_ALERT_WINDOW',
      'android.permission.FOREGROUND_SERVICE',
      'android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK',
      ...(adsNative ? [] : ['com.google.android.gms.permission.AD_ID']),
    ],
    ...(nativeFirebase ? { googleServicesFile: GOOGLE_SERVICES } : {}),
  },
  plugins: [
    'expo-router',
    'expo-sqlite',
    'expo-localization',
    'expo-sharing',
    'expo-font',
    // Dark, non-scrimmed system navigation bar so the app background shows through (edge-to-edge).
    ['expo-navigation-bar', { enforceContrast: false, style: 'light' }],
    ['expo-audio', { microphonePermission: false, recordAudioAndroid: false, enableBackgroundRecording: false, enableBackgroundPlayback: false }],
    [
      'expo-splash-screen',
      { image: './assets/splash-icon.png', imageWidth: 160, resizeMode: 'contain', backgroundColor: '#0B1018' },
    ],
    [
      'expo-build-properties',
      {
        android: {
          minSdkVersion: 29,
          compileSdkVersion: 36,
          targetSdkVersion: 36,
          enableMinifyInReleaseBuilds: true,
          enableShrinkResourcesInReleaseBuilds: true,
          // The AeroFMS Connector runs on the local network over ws:// (no TLS on LAN devices).
          usesCleartextTraffic: true,
        },
      },
    ],
    ...(nativeFirebase ? ['@react-native-firebase/app', '@react-native-firebase/crashlytics'] : []),
    ...(adsNative ? [['react-native-google-mobile-ads', { androidAppId: ADMOB_APP_ID, delayAppMeasurementInit: true, userTrackingUsageDescription: 'Ads' }] as [string, unknown]] : []),
    // react-native-nitro-google-signin needs no config plugin on Android: Credential Manager only uses the
    // web client id at runtime (EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID) and the module is autolinked.
    './plugins/withReleaseSigning.js',
  ],
  experiments: { typedRoutes: false },
  extra: {
    nativeFirebase,
    adsNative,
    admob: {
      bannerUnitId: process.env.AEROFMS_ADMOB_BANNER_ID ?? 'ca-app-pub-3940256099942544/9214589741',
      interstitialUnitId: process.env.AEROFMS_ADMOB_INTERSTITIAL_ID ?? 'ca-app-pub-3940256099942544/1033173712',
      rewardedUnitId: process.env.AEROFMS_ADMOB_REWARDED_ID ?? 'ca-app-pub-3940256099942544/5224354917',
    },
    eas: process.env.EAS_PROJECT_ID ? { projectId: process.env.EAS_PROJECT_ID } : undefined,
  },
})
